-- =============================================================================
-- LOAD PROD — Entity taxonomy: SYSTEM defaults + Moxuara customer copy
-- =============================================================================
-- Reverse-engineered from the LOCAL db (db_gcdr) on 2026-06-29 so PROD matches
-- local exactly: 8 entity_types, 33 SYSTEM nodes (customer_id NULL, is_system),
-- 33 Moxuara nodes (customer_id 84e0370e-…). Rows carry their real ids and
-- parent_entity_id, ordered roots-first so the self-FK resolves.
--
-- ⚠️ DESTRUCTIVE: TRUNCATEs `entities` first (to drop the sparse seed rows so
--    PROD ends up EXACTLY like local). TRUNCATE bypasses the is_system
--    BEFORE-DELETE trigger and the self-FK — a plain DELETE would be blocked.
--    Safe ONLY if no real customer taxonomy exists in PROD yet. PRE-CHECK:
--      SELECT customer_id, count(*) FROM entities WHERE is_deleted=false GROUP BY customer_id;
--    Expect only NULL (system seed) [+ maybe 84e0370e]. If OTHER customers show
--    up, STOP — do not run this.
--
-- ⚠️ NO BEGIN/COMMIT (Dokploy/postgres-js reject manual transactions). For
--    atomicity via CLI:  psql "<url>" --single-transaction -f thisfile.sql
-- =============================================================================

SET client_encoding TO 'UTF8';

-- 1) Type registry (idempotent; DO UPDATE so GROUP gets {GROUP,""} even if an
--    older seed already created it as {GROUP}).
INSERT INTO entity_types (tenant_id, entity_type, label, description, allowed_parent_types, is_active) VALUES
