  ('11111111-1111-1111-1111-111111111111','CLASSIFICATION_NODE','Classification · Node','RFC-0207 classification descendant (any depth).','{CLASSIFICATION_ENERGY,CLASSIFICATION_WATER,CLASSIFICATION_TEMPERATURE,CLASSIFICATION_NODE}'::text[],true),
  ('11111111-1111-1111-1111-111111111111','CLASSIFICATION_REPORTS','Relatõrios','Abre menu de relatõrios','{}'::text[],true),
  ('11111111-1111-1111-1111-111111111111','CLASSIFICATION_TEMPERATURE','Classification · Temperature','RFC-0207 temperature classification root.','{}'::text[],true),
  ('11111111-1111-1111-1111-111111111111','CLASSIFICATION_WATER','Classification · Water','RFC-0207 water classification root.','{}'::text[],true),
  ('11111111-1111-1111-1111-111111111111','EQUIPMENT','Equipment','An equipment node under a profile.','{PROFILE}'::text[],true),
  ('11111111-1111-1111-1111-111111111111','GROUP','Group','Top-level telemetry grouping (root-only).','{GROUP,""}'::text[],true),
  ('11111111-1111-1111-1111-111111111111','PROFILE','Profile','A profile under a group (e.g. CHILLER, FANCOIL).','{GROUP}'::text[],true)
ON CONFLICT (tenant_id, entity_type) DO UPDATE
  SET label = EXCLUDED.label,
      description = EXCLUDED.description,
      allowed_parent_types = EXCLUDED.allowed_parent_types,
      is_active = EXCLUDED.is_active;

-- 2) Clear existing entities (drops the seed rows). See PRE-CHECK above.
TRUNCATE TABLE entities;

